BEGIN; CREATE TEMP TABLE measured (LIKE user_mfa_backup_codes INCLUDING ALL); INSERT INTO measured(tenant_id,user_id,code_hash) SELECT '00000000-0000-0000-0000-000000000001',md5('user-'||i)::uuid,repeat('x',97) FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured')) FROM measured d; ROLLBACK;